void notsa::RelocateExeThunkConstants() {
    // One copy per read, static so it lives as long as the stubs that point at it
    static uint32 s_Copies[std::size(CODE_CONSTANT_READS)];

    size_t numRelocated{};
    for (size_t i = 0; i < std::size(CODE_CONSTANT_READS); i++) {
        const auto& read = CODE_CONSTANT_READS[i];

        // Both values must match, otherwise this is another exe (the compact one has real code here) and we leave it alone
        if (Read32(read.InstructionOperand) != read.CodeAddress || Read32(read.CodeAddress) != read.OriginalValue) {
            continue;
        }

        s_Copies[i] = read.OriginalValue;
        auto copyAddress = static_cast<uint32>(reinterpret_cast<uintptr_t>(&s_Copies[i]));
        try {
            ReversibleHooks::Utility::VirtualCopy(reinterpret_cast<void*>(read.InstructionOperand), &copyAddress, sizeof(copyAddress));
            numRelocated++;
        } catch (const std::exception& e) {
            NOTSA_LOG_ERR("Failed to relocate the code constant read at {:#x}: {}", read.InstructionOperand, e.what());
        }
    }

    NOTSA_LOG_INFO("Relocated {} of {} code constants read by the exe's thunk stubs", numRelocated, std::size(CODE_CONSTANT_READS));
}
